class _Layout(QObject):
    """Anchor / Dock: re-places the children of *host* whenever it is resized.
    spec = (x, y, w, h, rx, ry, rw, rh): x = x0 + rx * host width, width = w0 + rw * host width..."""

    def __init__(self, host):
        super().__init__(host)
        self.host, self.items = host, []
        host.installEventFilter(self)

    def eventFilter(self, obj, ev):
        if obj is self.host and ev.type() == QEvent.Type.Resize:
            self.apply()
        return False

    def apply(self):
        cw, ch = self.host.width(), self.host.height()
        for w, (x, y, ww, hh, rx, ry, rw, rh) in self.items:
            g = [round(x + rx * cw), round(y + ry * ch), max(0, round(ww + rw * cw)), max(0, round(hh + rh * ch))]
            held = getattr(w, "_rad_held", None)    # geometry a visual state / storyboard is animating
            if held:
                for i, (prop, cur) in enumerate((("Left", w.x()), ("Top", w.y()), ("Width", w.width()),
                                                 ("Height", w.height()))):
                    if prop in held:
                        g[i] = cur
            w.setGeometry(*g)


def _place(widget, host, spec):
    lay = host.findChild(_Layout, "", Qt.FindChildOption.FindDirectChildrenOnly)
    if lay is None:
        lay = _Layout(host)
    lay.items.append((widget, spec))


